import React, { useState } from "react";
import axios from "../utils/axios";
import { useNavigate } from "react-router-dom";
import { CheckCircle, XCircle } from "lucide-react";
import { signInWithPopup } from "firebase/auth";
import { auth, googleProvider } from "../firebase";

const Login = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [popup, setPopup] = useState({ show: false, message: "", type: "success" });
  const navigate = useNavigate();

  const showPopup = (message, type = "success") => {
    setPopup({ show: true, message, type });
    setTimeout(() => setPopup({ show: false, message: "", type: "success" }), 2500);
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await axios.post("/api/auth/login", { email, password });
      const user = res.data;
      localStorage.setItem("userId", user.id);
      localStorage.setItem("name", user.name);
      localStorage.setItem("email", user.email);
      showPopup("Welcome back to Spendly!", "success");
      setTimeout(() => navigate("/dashboard"), 800);
    } catch (err) {
      const msg = err?.response?.data?.message || "Login failed. Please try again.";
      showPopup(msg, "error");
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    try {
      const result = await signInWithPopup(auth, googleProvider);
      const firebaseUser = result.user;
      const res = await axios.post("/api/auth/google", {
        email: firebaseUser.email,
        name: firebaseUser.displayName,
        uid: firebaseUser.uid,
      });
      const user = res.data;
      localStorage.setItem("userId", user.id);
      localStorage.setItem("name", user.name);
      localStorage.setItem("email", user.email);
      showPopup("Welcome to Spendly!", "success");
      setTimeout(() => navigate("/dashboard"), 800);
    } catch (error) {
      console.error(error);
      showPopup("Google login failed", "error");
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 px-4">
      {popup.show && (
        <div className={`fixed top-6 left-1/2 -translate-x-1/2 z-50 flex items-center gap-2 px-4 py-2 rounded-md border text-sm shadow-sm ${popup.type === "success" ? "bg-white text-green-700 border-green-100" : "bg-white text-red-700 border-red-100"}`}>
          {popup.type === "success" ? <CheckCircle className="w-4 h-4" /> : <XCircle className="w-4 h-4" />}
          {popup.message}
        </div>
      )}
      <div className="w-full max-w-sm">
        <div className="mb-8">
          <h1 className="text-xl font-semibold text-gray-900">Spendly</h1>
          <p className="text-sm text-gray-500 mt-1">Track your spending with clarity</p>
        </div>
        <form onSubmit={handleLogin} className="space-y-3">
          <input type="email" placeholder="Email" value={email} required onChange={(e) => setEmail(e.target.value)} className="w-full px-3 py-2 border border-gray-200 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" />
          <input type="password" placeholder="Password" value={password} required onChange={(e) => setPassword(e.target.value)} className="w-full px-3 py-2 border border-gray-200 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" />
          <button type="submit" disabled={loading} className="w-full bg-gray-900 text-white py-2 rounded-md hover:bg-black transition disabled:opacity-60">
            {loading ? "Signing in..." : "Sign in"}
          </button>
          <div className="my-4 flex items-center gap-3">
            <div className="h-px bg-gray-200 flex-1" />
            <span className="text-xs text-gray-400">OR</span>
            <div className="h-px bg-gray-200 flex-1" />
          </div>
          <button type="button" onClick={handleGoogleLogin} className="w-full flex items-center justify-center gap-2 border border-gray-200 py-2.5 rounded-md hover:bg-gray-50 transition text-sm font-medium text-gray-700">
            <img src="https://www.svgrepo.com/show/355037/google.svg" className="w-4 h-4" alt="Google" />
            Continue with Google
          </button>
        </form>
        <p className="text-sm text-gray-500 mt-6">
          No account?{" "}
          <span onClick={() => navigate("/register")} className="text-gray-900 font-medium cursor-pointer hover:underline">Create one</span>
        </p>
      </div>
    </div>
  );
};

export default Login;
